using System.ClientModel;
using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (string query) => WebSearch.SearchAsync(query),
        "web_search",
        "Search the web for a query and return a list of result snippets with URLs."),

    AIFunctionFactory.Create(
        (string url) => WebSearch.FetchPageAsync(url),
        "fetch_page",
        "Fetch the text content of a web page given its URL."),

    AIFunctionFactory.Create(
        ([Description("Short title for the note")] string title,
         [Description("Body of the note")] string content) =>
        {
            notebook.Add(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Save a research note with a title and content."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "get_notes",
        "Retrieve all saved research notes."),
};

// ---------------------------------------------------------------------------
// Chat client with automatic tool invocation
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(new ApiKeyCredential(apiKey))
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// Agent system prompt
// ---------------------------------------------------------------------------
var systemPrompt = """
    You are a research agent. The user will give you a topic to research.

    Your workflow:
    1. Use `web_search` to find relevant information (run multiple searches with
       different queries to get broad coverage).
    2. Use `fetch_page` to read promising pages in detail.
    3. Use `save_note` to record key findings as you go.
    4. When you have gathered enough information, use `get_notes` to review your
       notes, then produce a well-structured summary for the user.

    Be thorough but concise. Cite sources with URLs where possible.
    """;

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍 AI Research Agent           ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║ Enter a topic to research.           ║");
Console.WriteLine("║ Type \"quit\" to exit.                 ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic))
        continue;
    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a summary:\n\n{topic}"),
    };

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\n⏳ Researching… (the agent will search, read, and take notes)\n");
    Console.ResetColor();

    try
    {
        var response = await client.GetResponseAsync(messages, chatOptions);
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("── Research Summary ──────────────────────────────");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.WriteLine();

        if (notebook.Count > 0)
        {
            Console.ForegroundColor = ConsoleColor.DarkYellow;
            Console.WriteLine($"📒 {notebook.Count} note(s) were saved during research.");
            Console.ResetColor();
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

