// Web Search tool — uses DuckDuckGo HTML to avoid API-key requirements
// ═══════════════════════════════════════════════════════════════════════════
static partial class WebSearch
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" }
        },
    };

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var results = new List<string>();
            // Extract result blocks from DuckDuckGo HTML
            foreach (Match m in ResultPattern().Matches(html))
            {
                var link = WebUtility.HtmlDecode(m.Groups[1].Value);
                var snippet = StripHtml(WebUtility.HtmlDecode(m.Groups[2].Value));
                if (!string.IsNullOrWhiteSpace(snippet))
                    results.Add($"- {snippet.Trim()}\n  URL: {link}");
                if (results.Count >= 8)
                    break;
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : "No results found.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    public static async Task<string> FetchPageAsync(string url)
    {
        try
        {
            var html = await Http.GetStringAsync(url);
            var text = StripHtml(html);
            // Collapse whitespace and limit length
            text = Whitespace().Replace(text, " ").Trim();
            return text.Length > 6000 ? text[..6000] + "…" : text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static string StripHtml(string html)
    {
        var text = HtmlTag().Replace(html, " ");
        return WebUtility.HtmlDecode(text);
    }

    [GeneratedRegex(
        """<a[^>]+href="([^"]+)"[^>]*class="[^"]*result__a[^"]*"[^>]*>.*?</a>.*?<a[^>]+class="[^"]*result__snippet[^"]*"[^>]*>(.*?)</a>""",
        RegexOptions.Singleline | RegexOptions.IgnoreCase)]
    private static partial Regex ResultPattern();

    [GeneratedRegex(@"<[^>]+>")]
    private static partial Regex HtmlTag();

    [GeneratedRegex(@"\s{2,}")]
    private static partial Regex Whitespace();
}

