// Notebook — simple in-memory note store
// ═══════════════════════════════════════════════════════════════════════════
sealed class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public int Count => _notes.Count;

    public void Add(string title, string content) =>
        _notes.Add((title, content, DateTime.UtcNow));

    public string GetAll()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var (t, c, ts) = _notes[i];
            sb.AppendLine($"[{i + 1}] {t} ({ts:HH:mm:ss UTC})");
            sb.AppendLine(c);
            sb.AppendLine();
        }
        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

